// Finite support-content improvements: no payment, eligibility or fulfilment change.
export const complaintStart='<section data-support-content="2026-10-10"><h2>Make a complaint</h2><p><a href="/contact?type=complaint">Contact SHIFT about a complaint</a>. Start your message with “Complaint” and tell us what happened, when it happened and what you would like us to put right. Include an existing reference if you have one and the best email address for a reply.</p><p>Keep a copy of your message. Do not include passwords, full card details or medical documents in the general contact form. If your complaint is about another clinic or pharmacy, use that provider’s own complaints route; SHIFT cannot investigate its private records.</p></section>';
export const paymentNote='<section data-support-content="2026-10-10"><h2>Make a payment query easier to resolve</h2><p>Check the seller named on your order confirmation and the payment description on your statement. In your message, give the payment date, amount, order reference if available and whether you are asking to cancel, correct a charge or check a refund. Do not send a bank statement or card number through the general form.</p><p>Keep a dated copy of your cancellation request and ask the seller to confirm the order status, any amount being refunded and how you will recognise the refund. This does not mean your cancellation rights depend on the seller agreeing. SHIFT cannot promise another seller’s decision or processing time.</p></section>';
export const accountRecovery='<section data-support-recovery="2026-10-11"><h3>Verification email missing or expired?</h3><ol><li>Check the inbox and junk folder for the address you used to register. Do not share the verification link: it belongs to your account.</li><li>Open <a href="/member-login">My Timber sign-in</a> and enter that same email address. If sign-in says the address still needs verification, use “Send a fresh verification email”. An expired or already-used verification link also opens that recovery option.</li><li>Use the fresh link, then return to sign in. A request confirmation alone does not prove the email arrived or the account was verified.</li></ol><h3>Forgotten your password?</h3><p>At <a href="/member-login">My Timber sign-in</a>, choose “Forgotten your password?”, enter your account email and choose “Send reset link”. Check your inbox and junk folder. Keep the reset link private; after changing your password, return to sign in.</p><h3>Still unable to get in?</h3><p>If the security check fails, retry it through the form. If it still fails, try a current browser. If no email arrives or a link will not work, <a href="/contact?type=Website%20or%20technical%20help">contact website support</a> with the page, approximate time and exact error wording. Never send a password, verification link or reset link. Do not create another account just to recover your existing progress.</p></section>';
export const disclaimerHandoff='<section data-support-recovery="2026-10-11"><h2>Choose the right help now</h2><p>For a life-threatening emergency, <a href="tel:999">call 999 now</a>. Do not wait for a SHIFT message, check-in or AI answer.</p><p>For urgent help that is not life-threatening, <a href="/help#urgent-help">find the urgent-care route for your part of the UK</a>. The Help Centre lists England, Scotland, Wales and Northern Ireland separately.</p><p>For a question about a prescription, side effect or changing treatment, contact your own prescriber or pharmacist. A website guide cannot decide what is safe for you personally.</p><p><a href="https://www.nhs.uk/nhs-services/urgent-and-emergency-care-services/when-to-call-999/">NHS: when to call 999</a>. Source checked 11 October 2026.</p></section>';
export const recoveryControls='<style data-support-controls="2026-10-11">#supportUtilities{display:flex;flex-wrap:wrap;gap:12px;align-items:center;max-width:1280px;margin:24px auto;padding:16px 24px;border-top:1px solid #747c65}#supportUtilities #askTimberLaunch,#supportUtilities #sstCookieSettings{position:static!important;inset:auto!important;transform:none!important;margin:0!important;min-height:44px!important;min-width:44px!important;z-index:auto!important}#askTimberLaunch:focus-visible,#sstCookieSettings:focus-visible{outline:3px solid #e9e6dc!important;outline-offset:3px!important}[data-support-recovery] a:focus-visible{outline:3px solid currentColor;outline-offset:3px}</style>';
export const controlRecovery=`<script data-support-control-recovery="2026-10-11">(()=>{function init(){const main=document.querySelector('main');if(main){const tools=document.createElement('section');tools.id='supportUtilities';tools.setAttribute('aria-label','Site tools');main.after(tools);const dock=()=>{for(const id of ['askTimberLaunch','sstCookieSettings']){const button=document.getElementById(id);if(button&&button.parentElement!==tools)tools.appendChild(button);}};dock();const dockObserver=new MutationObserver(()=>{dock();if(tools.children.length===2)dockObserver.disconnect();});if(tools.children.length<2)dockObserver.observe(document.body,{childList:true});}const launch=document.getElementById('askTimberLaunch'),drawer=document.getElementById('askTimberDrawer'),close=document.getElementById('askTimberClose');if(!launch||!drawer||!close)return;launch.setAttribute('aria-controls',drawer.id);drawer.setAttribute('role','region');drawer.setAttribute('aria-label','Ask Timber knowledge finder');const sync=()=>{const open=drawer.getAttribute('aria-hidden')==='false';launch.setAttribute('aria-expanded',String(open));drawer.inert=!open;};sync();new MutationObserver(sync).observe(drawer,{attributes:true,attributeFilter:['aria-hidden']});launch.addEventListener('click',()=>{drawer.inert=false;},true);close.addEventListener('click',()=>{queueMicrotask(()=>launch.focus());});drawer.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close.click();}});}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();})();</script>`;
export const whatsappSupport='<section data-shift-whatsapp="2026-10-23"><h2>Chat with SHIFT on WhatsApp</h2><p>For general website and account enquiries, <a href="https://wa.me/447932618313" target="_blank" rel="noopener noreferrer">chat with SHIFT on WhatsApp</a> on <strong>07932 618313</strong>.</p><p>WhatsApp opens separately. Please keep medical information, photos and documents in My Timber. This is not an emergency service.</p></section>';
export function supportContent(html,path){
 if(['/contact','/help'].includes(path)&&!html.includes('data-shift-whatsapp='))html=html.replace(/<h1\b[^>]*>[\s\S]*?<\/h1>/i,heading=>heading+whatsappSupport);
 if(['/contact','/help','/medical-disclaimer','/accessibility'].includes(path)){html=html.replace('</head>',recoveryControls+'</head>');html=html.replace('</body>',controlRecovery+'</body>');}
 if(path==='/medical-disclaimer'){const end='</div></section></div></main>';if(!html.includes(end))throw Error('Expected legal utility content boundary');html=html.replace(end,disclaimerHandoff+end);}
 if(path==='/help'){
   const old='<p>For registration, verification, sign-in or password-reset problems, start at <a href="/member-login">My Timber sign-in</a>. Never send your password by email.</p>';
   if(!html.includes(old))throw Error('Expected existing help account paragraph');
   html=html.replace(old,old+accountRecovery).replace('<h2>Health and urgent support</h2>','<h2 id="urgent-help">Health and urgent support</h2>');
 }

 if(path==='/complaints')html=html.replace(/<h2>What happens next<\/h2>/,complaintStart+'<h2>What happens next</h2>').replace('This route is not an emergency or clinical service: use NHS 111 or 999 where appropriate.','This route is not an emergency or clinical service. For urgent help, use <a href="/help">the routes for your part of the UK</a>; call 999 in a life-threatening emergency.');
 if(path==='/contact')html=html.replace('Questions, support, partnerships or press—send the detail securely and it will reach the Shift team.','Questions, support, partnerships or press—tell us what you need help with. For a complaint, start your message with “Complaint”. For a payment query, choose “My order” and include the payment date and reference.').replace('Call 999 in an emergency, or use NHS 111 for urgent medical help that is not life-threatening.','Call 999 in a life-threatening emergency. For other urgent help, choose the route for your part of the UK.').replace('href="https://111.nhs.uk/"','href="/help"').replace('Open NHS 111 →','Find urgent help →');
 if(path==='/terms-of-sale'||path==='/refunds')html=html.replace('</div></section></div></main>',paymentNote+'</div></section></div></main>');
 return html;
}